    for (var i = 0; i < n; i++) { var y0 = Math.round(hz * i / n), y1 = Math.round(hz * (i + 1) / n); R(g, K.sky[i], 0, y0, W, y1 - y0 + 1); }
    /* 兩色交界用棋盤格做像素式漸層 */
